/** M1l corpus generated by the ACTUAL unchanged editor encoder, not a copy. */
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {resolve} from 'node:path';
import {runInNewContext} from 'node:vm';

const editor=readFileSync(new URL('../../src/chaptera_server/web_ui/static/js/editor.mjs',import.meta.url),'utf8');
const start=editor.indexOf('function escapeHTML(');
const end=editor.indexOf('\nfunction option(',start);
assert.ok(start>=0 && end>start,'Review changed editor encoder boundaries');
const encode=runInNewContext(editor.slice(start,end)+'\ntextToHTML;');
export const textToEditorHTML=text=>String(encode(text));

export const cases=[
  {id:'basic',text:'Обычный перевод.'},
  {id:'paragraphs',text:'Первый абзац.\n\nВторой абзац.\n\nТретий абзац.'},
  {id:'line-breaks',text:'Первая строка.\nВторая строка.\nТретья строка.'},
  {id:'quotes',text:'Он сказал: "Да". She said: \'No\'.'},
  {id:'ampersand',text:'A & B && C; условие x < y > z.'},
  {id:'literal-markup',text:'Текст <script>alert("test")</script> и <b>не тег</b>.'},
  {id:'double-encoding',text:'Буквально &lt;b&gt;, &amp; и &#39;, а не повторное декодирование.'},
  {id:'unicode',text:'Русский текст 中文 日本語 😀 é — «да».'},
  {id:'crlf',text:'Первая строка.\r\nВторая строка.\r\n\r\nНовый абзац.\rКонец.'},
  {id:'blank-lines',text:'Начало.\n\n\n  \n\nКонец.'},
  {id:'tabs',text:'Один\tдва.  \n\tТри.\n\nЧетыре.'},
  {id:'nbsp',text:'Неразрывный пробел.\n\nЕщё один.'},
  {id:'punctuation',text:'!'},
  {id:'only-amp',text:'&'},
  {id:'only-quotes',text:'"\''},
  {id:'heading',text:'Глава 1\n\nНачало текста.'},
  {id:'heading-br',text:'Chapter\n0001:\n\nBody.'},
  {id:'heading-other',text:'Глава 2\n\nНе удалять чужой номер.'},
  {id:'heading-punctuation',text:'Глава 1..\n\nТекст.'},
  {id:'chapter-in-body',text:'Текст.\n\nГлава 1\n\nТекст продолжается.'},
  {id:'only-heading',text:'Chapter 1',blocked:true},
  {id:'service-marker',text:'Текст TSEG_12 в главе.',blocked:true},
  {id:'url-policy',text:'Посетите https://example.test',blocked:true},
  {id:'browser-first',text:'Первая глава: "A & B" и \'цитата\'.\nВторая строка: x < y > z.\n\nВторой абзац — русский текст 中文.\nБуквально &lt;tag&gt;, без повторного декодирования.'},
  {id:'browser-second',text:'Вторая глава: "кавычки" & амперсанд.\nПеренос строки сохраняется.\n\nТретий абзац: <b>это текст, не тег</b>.'},
];
for(let i=0;i<24;i++){
  const atoms=['Слово','"цитата"',"'слово'",'A & B','<p>литерал</p>','&amp;lt;'];
  const third=(i+Math.floor(i/6)+3)%6;
  cases.push({id:'combination-'+i,text:atoms[i%6]+'\n'+atoms[(i+1)%6]+'\n\n'+atoms[third]+'.'});
}
assert.equal(new Set(cases.map(c=>textToEditorHTML(c.text))).size,cases.length,
  'Every corpus case must exercise distinct encoded input');
export const rejectedHtml=[
  '<p> </p>', '<p>&unknown;</p>', '<p>&amp</p>', '<p>&#x3c;script&#x3e;</p>',
  '<p onclick="x">Text</p>', '<p>Text<br onclick="x">next</p>',
  '<p><script>alert(1)</script></p>', '<p><img src=x onerror=x></p>',
  '<p><p>Nested</p></p>', '<p>Text</p><div>More</div>',
];
export function fixtureData(){return {cases:cases.map(c=>({...c,html:textToEditorHTML(c.text)})),rejectedHtml};}
if(process.argv[1] && resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  process.stdout.write(JSON.stringify(fixtureData()));
}
